// ── Inject into each locale file ─────────────────────────────────────────────

const locales = ['en', 'sv', 'no', 'da', 'fr', 'es', 'de', 'nl', 'ar'];

for (const locale of locales) {
  const filePath = `${messagesDir}/${locale}.json`;
  const raw = readFileSync(filePath, 'utf-8');
  const json = JSON.parse(raw);

  const t = translations[locale] ?? translations.en;
  // Merge: preserve any existing service keys (landing page), add our new module keys
  json.service = { ...(json.service ?? {}), ...t };

  writeFileSync(filePath, JSON.stringify(json, null, 2) + '\n', 'utf-8');
  console.log(`[${locale}] ✓ Written`);
}

console.log('\nDone!');
